bash -lc "python - <<'PY'
import pathlib, re, sys
for p in pathlib.Path('src').glob('module_*.py'):
    text=p.read_text()
    def repl(m):
        typ=m.group(1).strip()
        if 'int'==typ:
            val='0'
        elif 'list\[int\]'==typ:
            val='[]'
        elif 'bool'==typ:
            val='False'
        elif 'str'==typ:
            val='""'
        elif 'dict\[str, int\]'==typ:
            val='{}'
        else:
            val='None'
        return f"{m.group(0).split('=')[0].strip()} = {val}"
    new=text
    new=re.sub(r'^(\w+\s*:\s*[^=]+)\s*=\s*[^#]+#\s*MYPY_ERROR', repl, new, flags=re.MULTILINE)
    p.write_text(new)
print('fixed')
PY
